import {timelineRate,validTimelineRate,configureTimelineRate} from './timeline-rate.js';
import {takeRateAllowsDrop} from './take-clock.js';
const choices=[['','기준 FPS 따름'],['24000/1001','23.976'],['30000/1001','29.97'],['60000/1001','59.94'],['custom','직접 입력']];
export function timelineRateMarkup(data){const rate=timelineRate(data),key=data.displayRate?rate.numerator+'/'+rate.denominator:'',selected=choices.some(([v])=>v===key)?key:'custom';return '<fieldset class="take-clock-fields"><legend>편집 격자</legend><label>프레임률<select aria-label="편집 격자 FPS" data-timeline-rate="preset">'+choices.map(([v,label])=>'<option value="'+v+'" '+(v===selected?'selected':'')+' '+(v==='custom'&&selected!=='custom'?'disabled':'')+'>'+label+'</option>').join('')+'</select></label><label>분자 / 분모<input aria-label="편집 격자 분수" data-timeline-rate="fraction" value="'+(data.displayRate?key:'')+'" placeholder="'+data.fps+'/1" spellcheck="false"></label><label>드롭 프레임 표기<input data-timeline-rate="drop" data-timeline-rate-locked="'+!takeRateAllowsDrop(rate)+'" type="checkbox" '+(data.displayDropFrame?'checked':'')+' '+(takeRateAllowsDrop(rate)?'':'disabled')+'></label></fieldset>';}
export function timelineRateInput(data,input){const field=input.dataset.timelineRate;if(field==='drop'){configureTimelineRate(data,timelineRate(data),input.checked);return;}let text=input.value.trim();if(field==='preset'&&text==='custom')return;if(!text){configureTimelineRate(data,null);return;}if(field==='preset'&&!choices.some(([v])=>v===text))throw Error('편집 격자 FPS를 확인하세요.');const match=/^(\d+)\s*\/\s*(\d+)$/.exec(text);if(!match)throw Error('편집 격자는 분자/분모로 입력하세요.');const next={numerator:Number(match[1]),denominator:Number(match[2])};configureTimelineRate(data,next,!!data.displayDropFrame&&takeRateAllowsDrop(next));if(!validTimelineRate(data))throw Error('편집 격자를 확인하세요.');}
